UPDATE sys_user
nickname = #{nickname}, password_hash = #{passwordHash}, employee_id = #{employeeId}, status = #{status},
WHERE id = #{id}

UPDATE sys_user
SET last_login_at = NOW(), last_login_ip = #{ip}
WHERE id = #{id}
